import { createRequire } from 'node:module'

// A category maps to the words that belong to it, e.g. `{ 乐: ['高兴', ...] }`.
export type SentiDict = Record<string, string[]>

export interface BosonNlpData {
  BosonNLP: Record<string, number>
  degree: Record<string, number>
  not: string[]
}

// The dictionaries are generated by `npm run dict:handle` and stay JSON files
// on disk: importing them statically would make TypeScript infer a type for
// every one of the ~100k keys. `createRequire` also keeps the same resolution
// as the previous CommonJS implementation.
const nodeRequire = createRequire(import.meta.url)

export const DUTIR = (nodeRequire('./dictionary/DUTIR.json') as { DUTIR: SentiDict }).DUTIR

export const HOWNET = (nodeRequire('./dictionary/HOWNET.json') as { HOWNET: SentiDict }).HOWNET

export const CHINESE_STOPWORDS = (nodeRequire('./dictionary/STOPWORDS.json') as {
  STOPWORDS: { chinese: string[] }
}).STOPWORDS.chinese

export const BOSON_NLP = nodeRequire('./dictionary/BosonNLP.json') as BosonNlpData
